before:
rule ("[CHARGE_BATTERY] RESET COOLDOWNS ON ULTIMATE") {
event {
Ongoing - Each Player;
Team 1;
All;
}
conditions {
And(Global.isGameplayActive, Compare((Event Player).enhancementId, ==, 6)) == True;
Is Using Ultimate(Event Player) == True;
}
actions {
Call Subroutine(resetAbilityCooldowns);
}
}

